/* ============================================================
   VIGHNA 26  -  THE PATH OF WISDOM
   Ganesh Chaturthi Game Design Contest
   Engine: Phaser 3  |  Build tool: Vite
   Theme: bright, colourful festival evening.
   Player: Mushak (the little mouse who carries the modak basket).
   All art is drawn by code (no external image files needed).
   ============================================================ */

import './style.css';
import Phaser from 'phaser';

const GAME_W = 1280;
const GAME_H = 720;
const LEVEL_W = 5400;
const NEED_WISDOM = 30;

// ---- festive colour palette ----
const COL_SKY_TOP = 0x2d1b4e;   // deep dusk purple
const COL_SKY_MID = 0xb9436b;   // festive pink
const COL_SKY_LOW = 0xff9d3d;   // marigold orange
const COL_GOLD = 0xffc94a;
const COL_MAGENTA = 0xff5e8f;
const COL_TEAL = 0x2fd4b0;
const COL_PURPLE = 0x9b5de5;

const IS_TOUCH = ('ontouchstart' in window) || navigator.maxTouchPoints > 0;

// Ganesha ji artwork, drawn by the user - embedded so no extra file needs to be placed
const GANESH_B64 = '';


/* ============================================================
   BOOT SCENE  -  draws every texture with code
   ============================================================ */
class BootScene extends Phaser.Scene {
  constructor() { super('Boot'); }

  preload() {
    this.load.image('ganesh', 'data:image/png;base64,' + GANESH_B64);
  }

  create() {
    const g = this.make.graphics({ add: false });

    // --- blank pixel, used for invisible physics bodies ---
    g.clear();
    g.fillStyle(0xffffff, 1); g.fillRect(0, 0, 8, 8);
    g.generateTexture('blank', 8, 8);

    /* ---------------- MUSHAK (decorated vahana) - this is the physics
       sprite that actually takes hits/bounces. Ganesha ji rides on top
       as a separate image that never flickers or reacts to damage -
       he stays calm and safe at all times. ---------------- */
    g.clear();
    g.fillStyle(COL_GOLD, 0.18); g.fillCircle(38, 42, 38);              // aura

    // tail with a small bell at the tip
    g.lineStyle(5, 0x8a8a92, 1);
    g.beginPath(); g.moveTo(62, 48); g.lineTo(84, 30); g.lineTo(78, 14);
    g.strokePath();
    g.fillStyle(COL_GOLD, 1); g.fillCircle(78, 14, 3.4);

    // body (grey mushak)
    g.fillStyle(0x9a9aa2, 1); g.fillEllipse(36, 46, 46, 32);
    g.fillStyle(0xc4c4cc, 1); g.fillEllipse(36, 53, 34, 18);            // belly

    // decorated saddle cloth - gold border, red cloth, tassel fringe
    g.fillStyle(COL_GOLD, 1); g.fillEllipse(36, 32, 38, 17);
    g.fillStyle(0xb5203a, 1); g.fillEllipse(36, 33, 32, 13);
    g.fillStyle(COL_GOLD, 0.95); g.fillCircle(36, 33, 5);               // lotus emblem
    g.fillStyle(0xb5203a, 1); g.fillCircle(36, 33, 2.6);
    g.fillStyle(COL_GOLD, 1);
    for (let i = 20; i <= 52; i += 7) g.fillCircle(i, 40, 2);           // hanging bells

    // head
    g.fillStyle(0x9a9aa2, 1); g.fillCircle(62, 32, 16);
    g.fillStyle(0x7a7a82, 1); g.fillCircle(50, 20, 9.5); g.fillCircle(66, 17, 9.5); // ear base
    g.fillStyle(0xffc7d9, 1); g.fillCircle(50, 20, 7); g.fillCircle(66, 17, 7);     // ear inner
    // tiny crown + tilak, matching the vahana's royal look
    g.fillStyle(COL_GOLD, 1); g.fillTriangle(58, 20, 62, 12, 66, 20);
    g.fillStyle(0xd8304a, 1); g.fillRect(60.5, 24, 3, 3);               // tilak
    // snout
    g.fillStyle(0xc9a9a4, 1); g.fillCircle(71, 36, 7);
    g.fillStyle(0x2a1a1a, 1); g.fillCircle(74, 36, 2);                  // nose tip
    g.fillStyle(0x1a1a1a, 1); g.fillCircle(66, 29, 2.6);                // eye

    // feet
    g.fillStyle(0x7a7a82, 1);
    g.fillRoundedRect(20, 60, 12, 7, 3);
    g.fillRoundedRect(42, 60, 12, 7, 3);

    g.generateTexture('player', 90, 70);

    /* ---------------- MODAK (main collectible) ---------------- */
    g.clear();
    g.fillStyle(COL_GOLD, 0.20); g.fillCircle(18, 18, 18);
    g.fillStyle(0xfff0c4, 1);
    g.beginPath(); g.moveTo(18, 3); g.lineTo(31, 27); g.lineTo(5, 27); g.closePath(); g.fillPath();
    g.fillStyle(0xe0a940, 1); g.fillRect(5, 25, 26, 5);
    g.lineStyle(1.4, 0xffffff, 0.55);
    g.lineBetween(13, 12, 18, 6); g.lineBetween(18, 6, 23, 12);
    g.generateTexture('modak', 36, 36);

    /* ---------------- FLOWER (bonus collectible) ---------------- */
    g.clear();
    g.fillStyle(COL_MAGENTA, 0.18); g.fillCircle(18, 18, 18);
    for (let i = 0; i < 5; i++) {
      const a = (Math.PI * 2 * i) / 5;
      g.fillStyle(0xff7fae, 1);
      g.fillEllipse(18 + Math.cos(a) * 8, 18 + Math.sin(a) * 8, 11, 7);
    }
    g.fillStyle(0xffd23f, 1); g.fillCircle(18, 18, 6);
    g.generateTexture('flower', 36, 36);

    /* ---------------- FIRECRACKER HAZARD (static, ground) ---------------- */
    g.clear();
    g.fillStyle(0x3d2a1a, 1); g.fillRoundedRect(4, 6, 20, 22, 3);
    g.fillStyle(COL_MAGENTA, 1); g.fillRect(4, 6, 20, 5);
    g.fillStyle(COL_TEAL, 1); g.fillRect(4, 16, 20, 5);
    g.fillStyle(0xffd23f, 1); g.fillCircle(14, 4, 3);
    g.lineStyle(2, 0xffffff, 0.8);
    g.lineBetween(14, 4, 10, -2); g.lineBetween(14, 4, 18, -2); g.lineBetween(14, 4, 14, -4);
    g.generateTexture('cracker', 28, 28);

    /* ---------------- CHAKRA (moving obstacle, spinning firework wheel) ---------------- */
    g.clear();
    g.fillStyle(0xff5e8f, 0.22); g.fillCircle(22, 22, 22);
    g.fillStyle(0x3a1030, 1); g.fillCircle(22, 22, 16);
    g.fillStyle(0xffd23f, 1);
    for (let i = 0; i < 8; i++) {
      const a = (Math.PI * 2 * i) / 8;
      g.fillTriangle(
        22, 22,
        22 + Math.cos(a) * 20, 22 + Math.sin(a) * 20,
        22 + Math.cos(a + 0.28) * 20, 22 + Math.sin(a + 0.28) * 20
      );
    }
    g.fillStyle(0xff5e8f, 1); g.fillCircle(22, 22, 7);
    g.fillStyle(0xfff0c4, 1); g.fillCircle(22, 22, 3);
    g.generateTexture('chakra', 44, 44);

    /* ---------------- diya (background decoration + spark fx) ---------------- */
    g.clear();
    g.fillStyle(0xffcc55, 0.16); g.fillCircle(10, 10, 10);
    g.fillStyle(0xfff0c4, 1); g.fillCircle(10, 10, 3.5);
    g.generateTexture('spark', 20, 20);

    g.clear();
    g.fillStyle(0x5c3a1e, 1); g.fillEllipse(14, 20, 22, 8);
    g.fillStyle(0xffb347, 1); g.fillEllipse(14, 12, 5, 9);
    g.fillStyle(0xfff0c4, 1); g.fillEllipse(14, 10, 2.6, 5);
    g.generateTexture('diya', 28, 26);

    /* ---------------- dhol player silhouette (background decoration) ---------------- */
    g.clear();
    g.fillStyle(0x1a1024, 1);
    g.fillEllipse(20, 62, 14, 6);                          // feet shadow
    g.fillRect(15, 40, 5, 22);                              // legs
    g.fillRect(24, 40, 5, 22);
    g.fillEllipse(22, 34, 13, 16);                          // torso
    g.fillCircle(22, 16, 7);                                // head
    g.fillRect(9, 24, 26, 16);                              // dhol drum
    g.fillStyle(0xffc94a, 1);
    g.fillRect(9, 24, 26, 3); g.fillRect(9, 37, 26, 3);     // drum rims
    g.fillStyle(0x1a1024, 1);
    g.fillRect(6, 20, 4, 26); g.fillRect(6, 20, 24, 4);     // arm + stick hint L
    g.fillRect(32, 20, 4, 26); g.fillRect(12, 20, 24, 4);   // arm + stick hint R
    g.generateTexture('dholi', 44, 68);

    /* ---------------- walking crowd figure silhouette (background decoration) ---------------- */
    g.clear();
    g.fillStyle(0x1a1024, 1);
    g.fillEllipse(12, 58, 11, 5);
    g.fillRect(7, 38, 5, 20);
    g.fillRect(14, 38, 5, 20);
    g.fillEllipse(12, 28, 11, 14);
    g.fillCircle(12, 12, 6.5);
    g.fillStyle(0xffb347, 0.9); g.fillCircle(5, 6, 2.2);    // held sparkler / lamp glow
    g.generateTexture('crowd', 24, 60);

    g.destroy();
    this.scene.start('Menu');
  }
}

/* ============================================================
   Shared helper: colourful festive sky, used by every scene
   ============================================================ */
function paintFestiveSky(scene, width) {
  // sky gradient (built from stacked bands so it works without shaders)
  const bands = 40;
  const sky = scene.add.graphics().setScrollFactor(0).setDepth(-12);
  for (let i = 0; i < bands; i++) {
    const t = i / (bands - 1);
    const col = Phaser.Display.Color.Interpolate.ColorWithColor(
      Phaser.Display.Color.ValueToColor(COL_SKY_TOP),
      Phaser.Display.Color.ValueToColor(t < 0.55
        ? COL_SKY_MID
        : COL_SKY_LOW),
      1, Math.min(1, t * 1.3)
    );
    sky.fillStyle(Phaser.Display.Color.GetColor(col.r, col.g, col.b), 1);
    sky.fillRect(0, (GAME_H / bands) * i, GAME_W, GAME_H / bands + 1);
  }

  // glowing moon-lantern
  const glow = scene.add.graphics().setScrollFactor(0).setDepth(-11);
  for (let i = 10; i > 0; i--) {
    glow.fillStyle(0xfff0c4, 0.035);
    glow.fillCircle(GAME_W * 0.80, GAME_H * 0.20, i * 20);
  }
  glow.fillStyle(0xfff6dd, 1); glow.fillCircle(GAME_W * 0.80, GAME_H * 0.20, 46);
  glow.fillStyle(0xffd98a, 1); glow.fillCircle(GAME_W * 0.80, GAME_H * 0.20, 46).setAlpha(0.5);

  // a giant, serene Ganesha silhouette watches over the journey from a
  // distant hill - moves very slowly (low scroll factor) so it stays
  // visible for most of the level, like a far-off mountain shrine
  const dgx = GAME_W * 0.28, dgy = GAME_H * 0.30, dgs = 2.6;
  const divine = scene.add.graphics().setScrollFactor(0.06).setDepth(-9.5);
  for (let i = 14; i > 0; i--) {
    divine.fillStyle(0xffe9ad, 0.028);
    divine.fillCircle(dgx, dgy, i * 16 * dgs * 0.5);
  }
  // soft god-rays
  divine.fillStyle(0xffe9ad, 0.06);
  for (let a = -60; a <= 60; a += 20) {
    const rad = (a * Math.PI) / 180;
    divine.beginPath();
    divine.moveTo(dgx, dgy);
    divine.lineTo(dgx + Math.sin(rad) * 260, dgy + 260);
    divine.lineTo(dgx + Math.sin(rad + 0.09) * 260, dgy + 260);
    divine.closePath(); divine.fillPath();
  }
  divine.fillStyle(0x2a1f45, 0.75);
  divine.fillEllipse(dgx, dgy + 30 * dgs, 22 * dgs, 9 * dgs);            // seat
  divine.fillEllipse(dgx, dgy + 12 * dgs, 18 * dgs, 17 * dgs);           // body
  // big round ears, drawn wide so they clearly stick out either side
  divine.fillEllipse(dgx - 15 * dgs, dgy - 5 * dgs, 12 * dgs, 16 * dgs);
  divine.fillEllipse(dgx + 15 * dgs, dgy - 5 * dgs, 12 * dgs, 16 * dgs);
  // head
  divine.fillCircle(dgx, dgy - 6 * dgs, 11 * dgs);
  // curling trunk - the one feature that makes the silhouette read as Ganesha
  // (drawn with plain line segments - Phaser Graphics has no quadraticCurveTo)
  divine.lineStyle(3.4 * dgs, 0x2a1f45, 0.75);
  divine.beginPath();
  divine.moveTo(dgx, dgy - 1 * dgs);
  divine.lineTo(dgx - 5 * dgs, dgy + 5 * dgs);
  divine.lineTo(dgx - 8 * dgs, dgy + 10 * dgs);
  divine.lineTo(dgx - 1 * dgs, dgy + 13 * dgs);
  divine.strokePath();
  // small tusk
  divine.fillStyle(0xfff3cf, 0.5);
  divine.fillTriangle(dgx + 3 * dgs, dgy + 2 * dgs, dgx + 8 * dgs, dgy + 6 * dgs, dgx + 3 * dgs, dgy + 8 * dgs);
  divine.fillStyle(0xffd98a, 0.9); divine.fillCircle(dgx, dgy - 17 * dgs, 4 * dgs); // crown glow

  // twinkling stars, upper sky only
  const stars = scene.add.graphics().setScrollFactor(0.05).setDepth(-10);
  for (let i = 0; i < 90; i++) {
    const x = Phaser.Math.Between(0, GAME_W);
    const y = Phaser.Math.Between(0, GAME_H * 0.4);
    stars.fillStyle(0xffffff, Phaser.Math.FloatBetween(0.2, 0.9));
    stars.fillCircle(x, y, Phaser.Math.FloatBetween(0.6, 1.6));
  }

  // colourful bunting flags (toran) strung across the top
  const buntColors = [COL_MAGENTA, COL_TEAL, COL_GOLD, COL_PURPLE, 0xff7f4d];
  const bunt = scene.add.graphics().setScrollFactor(0.2).setDepth(-9);
  let flagX = -20;
  let c = 0;
  while (flagX < width * 0.6) {
    bunt.fillStyle(buntColors[c % buntColors.length], 0.9);
    bunt.fillTriangle(flagX, 26, flagX + 22, 26, flagX + 11, 52);
    flagX += 26; c++;
  }

  // bazaar shopfronts, silhouette with hanging lanterns - replaces plain hills
  const shopColors = [0x2c1a3d, 0x241531, 0x33203f];
  const far = scene.add.graphics().setScrollFactor(0.18).setDepth(-8);
  let sx = 0, si = 0;
  while (sx < width + 120) {
    const w = Phaser.Math.Between(90, 150);
    const h = Phaser.Math.Between(140, 210);
    far.fillStyle(shopColors[si % shopColors.length], 1);
    far.fillRect(sx, GAME_H - h, w, h);
    far.fillTriangle(sx - 6, GAME_H - h, sx + w / 2, GAME_H - h - 34, sx + w + 6, GAME_H - h); // roof
    far.fillStyle(0xffcc55, 0.9);
    for (let lx = sx + 14; lx < sx + w - 10; lx += 26) {
      far.fillCircle(lx, GAME_H - h + 18, 2.4);              // window lantern
    }
    sx += w + 6; si++;
  }

  const near = scene.add.graphics().setScrollFactor(0.42).setDepth(-7);
  let nx = 30, ni = 0;
  while (nx < width + 120) {
    const w = Phaser.Math.Between(80, 130);
    const h = Phaser.Math.Between(90, 150);
    near.fillStyle(shopColors[(ni + 1) % shopColors.length], 1);
    near.fillRect(nx, GAME_H - h, w, h);
    near.fillStyle(0xffb347, 0.85);
    for (let lx = nx + 10; lx < nx + w - 8; lx += 22) {
      near.fillCircle(lx, GAME_H - h + 14, 2);
    }
    nx += w + 10; ni++;
  }

  // string lights swagged between the shopfronts
  const bulbColors = [COL_MAGENTA, COL_TEAL, COL_GOLD, COL_PURPLE];
  const wire = scene.add.graphics().setScrollFactor(0.42).setDepth(-6);
  let wx = 0, bi = 0;
  while (wx < width) {
    wire.lineStyle(1, 0x5a4030, 0.6);
    wire.beginPath();
    wire.moveTo(wx, GAME_H - 150);
    wire.lineTo(wx + 90, GAME_H - 118);
    wire.lineTo(wx + 180, GAME_H - 150);
    wire.strokePath();
    for (let t = 0.15; t < 1; t += 0.2) {
      const bx = wx + t * 180;
      const by = GAME_H - 150 + Math.sin(t * Math.PI) * 32;
      wire.fillStyle(bulbColors[bi % bulbColors.length], 1);
      wire.fillCircle(bx, by, 3);
      bi++;
    }
    wx += 180;
  }

  // dhol players and walking crowd, decorative only, in front of the shops
  for (let x = 60; x < width; x += Phaser.Math.Between(220, 340)) {
    const dh = scene.add.image(x, GAME_H - 46, 'dholi').setScrollFactor(0.55).setDepth(2.5);
    scene.tweens.add({
      targets: dh, angle: 4, duration: 260, yoyo: true, repeat: -1,
      delay: Phaser.Math.Between(0, 200)
    });
    for (let i = 0; i < Phaser.Math.Between(2, 3); i++) {
      const cx = x + Phaser.Math.Between(-90, 90);
      const cw = scene.add.image(cx, GAME_H - 42, 'crowd').setScrollFactor(0.55).setDepth(2.5)
        .setScale(Phaser.Math.FloatBetween(0.85, 1.05));
      scene.tweens.add({
        targets: cw, x: cx + Phaser.Math.Between(-14, 14),
        duration: Phaser.Math.Between(900, 1400), yoyo: true, repeat: -1
      });
    }
  }

  // rows of diyas glowing along the horizon
  for (let x = 40; x < width; x += Phaser.Math.Between(150, 260)) {
    const d = scene.add.image(x, GAME_H - 118, 'diya')
      .setScrollFactor(0.42).setDepth(-6).setScale(1.1);
    scene.tweens.add({
      targets: d, alpha: 0.7, duration: Phaser.Math.Between(700, 1300),
      yoyo: true, repeat: -1, ease: 'Sine.easeInOut'
    });
  }
}

/* ============================================================
   MENU SCENE
   ============================================================ */
class MenuScene extends Phaser.Scene {
  constructor() { super('Menu'); }

  create() {
    paintFestiveSky(this, GAME_W);

    this.add.text(GAME_W / 2, 148, 'VIGHNA 26', {
      fontFamily: 'Georgia, serif', fontSize: '108px', color: '#ffc94a'
    }).setOrigin(0.5).setShadow(0, 0, '#ff5e8f', 30, false, true);

    this.add.text(GAME_W / 2, 230, 'T H E   P A T H   O F   W I S D O M', {
      fontFamily: 'Georgia, serif', fontSize: '24px', color: '#fff0c4'
    }).setOrigin(0.5).setAlpha(0.9);

    this.add.text(GAME_W / 2, 300,
      'Mushak carries Ganesha ji through the lantern-lit bazaar,\npast the dhol players and the crowd, toward the sacred pandal.',
      { fontFamily: 'Georgia, serif', fontSize: '20px', color: '#ffe3c2', align: 'center', lineSpacing: 8 }
    ).setOrigin(0.5);

    const controls = IS_TOUCH
      ? 'Use the on-screen buttons to move and jump'
      : 'A / D  or  Arrow Keys to move        SPACE / W to jump';

    this.add.text(GAME_W / 2, 400, controls, {
      fontFamily: 'Georgia, serif', fontSize: '19px', color: '#ffd98a'
    }).setOrigin(0.5);

    this.add.text(GAME_W / 2, 440,
      `Collect ${NEED_WISDOM} wisdom to open the pandal gate`,
      { fontFamily: 'Georgia, serif', fontSize: '19px', color: '#ffd98a' }
    ).setOrigin(0.5);

    const btn = this.add.rectangle(GAME_W / 2, 545, 300, 66, 0xffc94a, 0.16)
      .setStrokeStyle(2, COL_GOLD).setInteractive({ useHandCursor: true });
    const btnText = this.add.text(GAME_W / 2, 545, 'BEGIN THE PATH', {
      fontFamily: 'Georgia, serif', fontSize: '26px', color: '#ffc94a'
    }).setOrigin(0.5);
    this.tweens.add({ targets: [btn, btnText], alpha: 0.55, duration: 900, yoyo: true, repeat: -1 });

    this.add.text(GAME_W / 2, GAME_H - 40, 'गणपति बप्पा मोरया', {
      fontFamily: 'Georgia, serif', fontSize: '22px', color: '#ffc94a'
    }).setOrigin(0.5).setAlpha(0.85);

    const start = () => this.scene.start('Game');
    btn.on('pointerdown', start);
    this.input.keyboard.on('keydown-SPACE', start);
    this.input.keyboard.on('keydown-ENTER', start);
  }
}

/* ============================================================
   GAME SCENE
   ============================================================ */
class GameScene extends Phaser.Scene {
  constructor() { super('Game'); }

  create() {
    this.wisdom = 0;
    this.lives = 3;
    this.invulnerable = false;
    this.finished = false;
    this.startTime = this.time.now;
    this.checkpoint = { x: 90, y: 560 };
    this.coyote = 0;      // small grace window after leaving a ledge
    this.jumpBuffer = 0;  // remembers a jump press just before landing

    this.physics.world.setBounds(0, 0, LEVEL_W, GAME_H + 400);
    this.cameras.main.setBounds(0, 0, LEVEL_W, GAME_H);

    paintFestiveSky(this, LEVEL_W);

    this.platforms = this.physics.add.staticGroup();
    this.hazards = this.physics.add.group({ allowGravity: false, immovable: true });
    this.pickups = this.physics.add.group({ allowGravity: false, immovable: true });

    this.buildLevel();
    this.buildPlayer();
    this.buildPandal();
    this.buildHUD();
    this.buildControls();

    this.physics.add.collider(this.player, this.platforms);
    this.physics.add.overlap(this.player, this.pickups, this.collect, null, this);
    this.physics.add.overlap(this.player, this.hazards, this.takeDamage, null, this);

    this.cameras.main.startFollow(this.player, true, 0.09, 0.09);
    this.cameras.main.fadeIn(600, 0, 0, 0);
  }

  /* ---------- level geometry ---------- */
  addPlatform(x, y, w, h, colorSet = 0) {
    const rangoli = [
      [COL_MAGENTA, COL_GOLD], [COL_TEAL, COL_GOLD], [COL_PURPLE, COL_MAGENTA]
    ][colorSet % 3];

    const gfx = this.add.graphics().setDepth(2);
    gfx.fillStyle(0x2c1e40, 1); gfx.fillRect(x, y, w, h);
    gfx.fillStyle(rangoli[0], 1); gfx.fillRect(x, y, w, 6);
    gfx.fillStyle(rangoli[1], 0.9); gfx.fillRect(x, y + 6, w, 3);
    // little rangoli dots along the top edge
    for (let i = x + 18; i < x + w; i += 30) {
      gfx.fillStyle(COL_GOLD, 0.85); gfx.fillCircle(i, y + 12, 3);
    }
    gfx.lineStyle(1, 0x160f26, 0.9);
    for (let i = x + 44; i < x + w; i += 44) gfx.lineBetween(i, y + 8, i, y + h);

    const body = this.platforms.create(x + w / 2, y + h / 2, 'blank');
    body.setDisplaySize(w, h).refreshBody().setVisible(false);
  }

  addCrackers(x, y, count) {
    for (let i = 0; i < count; i++) {
      const s = this.hazards.create(x + i * 30 + 14, y - 12, 'cracker').setDepth(3);
      s.body.setSize(18, 22).setOffset(5, 4);
      this.tweens.add({
        targets: s, angle: Phaser.Math.Between(-4, 4), duration: 300,
        yoyo: true, repeat: -1, delay: Phaser.Math.Between(0, 300)
      });
    }
  }

  addChakra(x, y, range) {
    const v = this.hazards.create(x, y, 'chakra').setDepth(4);
    v.body.setCircle(17, 5, 5);
    v.minY = y - range;
    v.maxY = y + range;
    v.setVelocityY(90);
    this.tweens.add({ targets: v, angle: 360, duration: 1400, repeat: -1 });
  }

  addPickup(x, y, kind) {
    const isFlower = kind === 'flower';
    const o = this.pickups.create(x, y, isFlower ? 'flower' : 'modak').setDepth(4);
    o.value = isFlower ? 15 : 5;
    o.kind = kind;
    o.body.setCircle(15, 3, 3);
    this.tweens.add({
      targets: o, scale: 1.18, duration: 800, yoyo: true, repeat: -1,
      ease: 'Sine.easeInOut', delay: Phaser.Math.Between(0, 600)
    });
    this.tweens.add({
      targets: o, y: y - 8, duration: 1200, yoyo: true, repeat: -1,
      ease: 'Sine.easeInOut', delay: Phaser.Math.Between(0, 600)
    });
  }

  buildLevel() {
    const G = 664;

    this.addPlatform(0, G, 880, 60, 0);
    this.addPlatform(1040, G, 620, 60, 1);
    this.addPlatform(1850, G, 520, 60, 2);
    this.addPlatform(2560, G, 840, 60, 0);

    this.addPlatform(560, 520, 190, 26, 1);
    this.addPlatform(900, 448, 170, 26, 2);
    this.addPlatform(1300, 500, 200, 26, 0);
    this.addPlatform(1690, 430, 170, 26, 1);
    this.addPlatform(2060, 512, 200, 26, 2);
    this.addPlatform(2400, 440, 180, 26, 0);
    this.addPlatform(2760, 500, 190, 26, 1);

    this.addCrackers(360, G, 4);
    this.addCrackers(1230, G, 4);
    this.addCrackers(2050, G, 5);
    this.addCrackers(2700, G, 4);

    this.addChakra(980, 500, 110);
    this.addChakra(1760, 470, 130);
    this.addChakra(2470, 500, 120);

    this.addPickup(250, 590, 'modak');
    this.addPickup(640, 460, 'modak');
    this.addPickup(700, 460, 'modak');
    this.addPickup(975, 390, 'flower');
    this.addPickup(1140, 590, 'modak');
    this.addPickup(1380, 440, 'modak');
    this.addPickup(1440, 440, 'modak');
    this.addPickup(1760, 372, 'flower');
    this.addPickup(1950, 590, 'modak');
    this.addPickup(2130, 452, 'modak');
    this.addPickup(2480, 382, 'flower');
    this.addPickup(2820, 442, 'modak');
    this.addPickup(2880, 442, 'modak');
    this.addPickup(3060, 590, 'modak');

    // ---- extended stretch: bazaar deepens, closer to the pandal ----
    this.addPlatform(3400, G, 560, 60, 1);
    this.addPlatform(4160, G, 520, 60, 2);
    this.addPlatform(4880, G, 400, 60, 0);

    this.addPlatform(3720, 520, 190, 26, 0);
    this.addPlatform(4020, 448, 170, 26, 1);
    this.addPlatform(4340, 500, 200, 26, 2);
    this.addPlatform(4620, 430, 170, 26, 0);
    this.addPlatform(4780, 512, 190, 26, 1);
    this.addPlatform(5060, 440, 180, 26, 2);

    this.addCrackers(3480, G, 4);
    this.addCrackers(4260, G, 5);
    this.addCrackers(4980, G, 4);

    this.addChakra(3860, 500, 110);
    this.addChakra(4460, 470, 130);
    this.addChakra(5120, 500, 100);

    this.addPickup(3560, 460, 'modak');
    this.addPickup(3620, 460, 'modak');
    this.addPickup(3900, 390, 'flower');
    this.addPickup(4090, 400, 'modak');
    this.addPickup(4380, 440, 'modak');
    this.addPickup(4440, 440, 'modak');
    this.addPickup(4660, 372, 'flower');
    this.addPickup(4840, 590, 'modak');
    this.addPickup(5000, 452, 'modak');
    this.addPickup(5100, 382, 'flower');
    this.addPickup(5180, 442, 'modak');
  }

  buildPlayer() {
    this.player = this.physics.add.sprite(this.checkpoint.x, this.checkpoint.y, 'player');
    this.player.setDepth(6);
    this.player.setScale(0.9); // mushak at a normal, readable size
    this.player.body.setSize(50, 32).setOffset(14, 32);
    this.player.setCollideWorldBounds(true);
    this.player.setBounce(0.03);
    this.player.setMaxVelocity(340, 1100);

    // Ganesha ji rides on the mushak's back. This is a SEPARATE image on
    // purpose: it never flickers, shrinks or reacts when the mushak is
    // hit - he always stays calm, safe and visible. Only the mushak
    // (the vahana) shows any impact. Kept at a normal, modest size.
    this.ganeshRider = this.add.image(this.player.x, this.player.y, 'ganesh')
      .setOrigin(0.5, 1)
      .setDisplaySize(52, 80)
      .setDepth(6.5);
    this.syncGaneshRider();
  }

  syncGaneshRider() {
    // keeps Ganesha ji seated on the mushak every frame, facing the same way
    this.ganeshRider.setPosition(this.player.x, this.player.y - 6);
    this.ganeshRider.setFlipX(this.player.flipX);
  }

  buildPandal() {
    const tx = LEVEL_W - 220, ty = 664;
    this.templeX = tx;
    const g = this.add.graphics().setDepth(2);

    for (let i = 10; i > 0; i--) {
      g.fillStyle(COL_GOLD, 0.035);
      g.fillCircle(tx, ty - 150, i * 26);
    }
    // pandal base
    g.fillStyle(0x3a2456, 1); g.fillRect(tx - 130, ty - 55, 260, 55);
    g.fillStyle(0x4a2f6b, 1); g.fillRect(tx - 108, ty - 205, 216, 150);
    // domed roof
    g.fillStyle(COL_MAGENTA, 1);
    g.beginPath();
    g.moveTo(tx, ty - 350); g.lineTo(tx + 90, ty - 205); g.lineTo(tx - 90, ty - 205);
    g.closePath(); g.fillPath();
    // gold trims and fairy lights
    g.fillStyle(COL_GOLD, 0.85);
    g.fillRect(tx - 112, ty - 210, 224, 6);
    g.fillRect(tx - 134, ty - 60, 268, 6);
    for (let i = -100; i <= 100; i += 20) {
      g.fillStyle(i % 40 === 0 ? COL_TEAL : COL_GOLD, 1);
      g.fillCircle(tx + i, ty - 210, 3);
    }
    g.fillCircle(tx, ty - 362, 12);
    // doorway glow
    g.fillStyle(0x1c1030, 1); g.fillRect(tx - 36, ty - 150, 72, 90);
    g.fillStyle(0xffe3a0, 0.5); g.fillRect(tx - 28, ty - 142, 56, 82);
    // small idol silhouette inside, seated, respectful and symbolic
    g.fillStyle(0x2a1a3c, 1);
    g.fillEllipse(tx, ty - 92, 26, 14);      // seat
    g.fillEllipse(tx, ty - 112, 20, 26);     // body
    g.fillCircle(tx, ty - 132, 12);          // head
    g.fillTriangle(tx - 15, ty - 130, tx - 26, ty - 138, tx - 14, ty - 122); // ear/trunk hint L
    g.fillTriangle(tx + 15, ty - 130, tx + 26, ty - 138, tx + 14, ty - 122); // ear R
    g.fillStyle(COL_GOLD, 0.9); g.fillCircle(tx, ty - 150, 4); // crown glow

    this.templeLight = this.add.circle(tx, ty - 105, 34, 0xffe3a0, 0.3).setDepth(3);
    this.tweens.add({
      targets: this.templeLight, alpha: 0.6, scale: 1.25,
      duration: 1300, yoyo: true, repeat: -1, ease: 'Sine.easeInOut'
    });

    // diyas either side of the entrance
    this.add.image(tx - 70, ty - 40, 'diya').setDepth(3).setScale(1.4);
    this.add.image(tx + 70, ty - 40, 'diya').setDepth(3).setScale(1.4);

    this.gateText = this.add.text(tx, ty - 410, '', {
      fontFamily: 'Georgia, serif', fontSize: '20px', color: '#ffc94a'
    }).setOrigin(0.5).setDepth(6);

    this.templeZone = this.add.zone(tx, ty - 110, 100, 130);
    this.physics.add.existing(this.templeZone, true);
    this.physics.add.overlap(this.player, this.templeZone, this.tryEnterTemple, null, this);
  }

  /* ---------- HUD ---------- */
  buildHUD() {
    const style = { fontFamily: 'Georgia, serif', fontSize: '24px', color: '#fff0c4' };

    this.add.rectangle(0, 0, GAME_W, 74, 0x1c1030, 0.5)
      .setOrigin(0, 0).setScrollFactor(0).setDepth(20);

    this.wisdomText = this.add.text(28, 24, '', style).setScrollFactor(0).setDepth(21);
    this.livesText = this.add.text(GAME_W / 2 - 70, 24, '', style).setScrollFactor(0).setDepth(21);
    this.timeText = this.add.text(GAME_W - 190, 24, '', style).setScrollFactor(0).setDepth(21);

    this.toast = this.add.text(GAME_W / 2, 120, '', {
      fontFamily: 'Georgia, serif', fontSize: '26px', color: '#ffc94a'
    }).setOrigin(0.5).setScrollFactor(0).setDepth(22).setAlpha(0);

    this.updateHUD();
  }

  updateHUD() {
    this.wisdomText.setText(`WISDOM  ${this.wisdom} / ${NEED_WISDOM}`);
    this.livesText.setText(`DIYAS  ${'◆ '.repeat(this.lives).trim()}`);
  }

  showToast(msg) {
    this.toast.setText(msg).setAlpha(1);
    this.tweens.killTweensOf(this.toast);
    this.tweens.add({ targets: this.toast, alpha: 0, delay: 1200, duration: 500 });
  }

  /* ---------- input (keyboard + touch) ---------- */
  buildControls() {
    this.cursors = this.input.keyboard.createCursorKeys();
    this.keys = this.input.keyboard.addKeys('A,D,W,SPACE,R');
    this.touch = { left: false, right: false, jump: false };

    if (!IS_TOUCH) return;

    const mk = (x, y, r, label) => {
      const c = this.add.circle(x, y, r, COL_GOLD, 0.16)
        .setStrokeStyle(2, COL_GOLD, 0.7)
        .setScrollFactor(0).setDepth(30).setInteractive({ useHandCursor: true });
      this.add.text(x, y, label, {
        fontFamily: 'Georgia, serif', fontSize: '30px', color: '#ffe3c2'
      }).setOrigin(0.5).setScrollFactor(0).setDepth(31);
      return c;
    };

    const L = mk(110, GAME_H - 110, 58, '<');
    const R = mk(260, GAME_H - 110, 58, '>');
    const J = mk(GAME_W - 140, GAME_H - 120, 74, '^');

    const bind = (btn, key) => {
      btn.on('pointerdown', () => { this.touch[key] = true; });
      btn.on('pointerup', () => { this.touch[key] = false; });
      btn.on('pointerout', () => { this.touch[key] = false; });
    };
    bind(L, 'left'); bind(R, 'right'); bind(J, 'jump');

    this.input.addPointer(2);
  }

  /* ---------- gameplay events ---------- */
  collect(player, orb) {
    const value = orb.value;
    const kind = orb.kind;
    const x = orb.x, y = orb.y;
    orb.destroy();

    this.wisdom += value;
    this.updateHUD();

    for (let i = 0; i < 8; i++) {
      const s = this.add.image(x, y, 'spark').setDepth(7)
        .setTint(value > 5 ? 0xff8fbf : 0xffe07a);
      this.tweens.add({
        targets: s,
        x: x + Phaser.Math.Between(-46, 46),
        y: y + Phaser.Math.Between(-46, 46),
        alpha: 0, scale: 0.2, duration: 560,
        onComplete: () => s.destroy()
      });
    }

    this.showToast(kind === 'flower' ? 'आरती !  +15' : 'ढोल !  +5');
    if (this.wisdom >= NEED_WISDOM && !this.gateOpen) {
      this.gateOpen = true;
      this.showToast('THE PANDAL GATE IS OPEN');
    }
  }

  takeDamage() {
    if (this.invulnerable || this.finished) return;
    this.invulnerable = true;
    this.lives -= 1;
    this.updateHUD();
    this.cameras.main.shake(220, 0.012);
    this.cameras.main.flash(180, 255, 94, 143);

    if (this.lives <= 0) return this.endGame(false);

    this.player.setVelocity(0, 0);
    this.player.setPosition(this.checkpoint.x, this.checkpoint.y);
    this.showToast('A VIGHNA STOPPED YOU');

    this.tweens.add({
      targets: this.player, alpha: 0.25, duration: 120, yoyo: true, repeat: 6,
      onComplete: () => { this.player.setAlpha(1); this.invulnerable = false; }
    });
  }

  tryEnterTemple() {
    if (this.finished) return;
    if (this.wisdom >= NEED_WISDOM) this.endGame(true);
  }

  endGame(won) {
    this.finished = true;
    this.physics.pause();
    const seconds = Math.floor((this.time.now - this.startTime) / 1000);
    this.cameras.main.fadeOut(500, 0, 0, 0);
    this.time.delayedCall(560, () => {
      this.scene.start('End', { won, wisdom: this.wisdom, lives: this.lives, seconds });
    });
  }

  /* ---------- per-frame loop ---------- */
  update(time, delta) {
    if (this.finished) return;
    this.syncGaneshRider();

    const dt = delta / 1000;
    const onGround = this.player.body.blocked.down || this.player.body.touching.down;
    const left = this.cursors.left.isDown || this.keys.A.isDown || this.touch.left;
    const right = this.cursors.right.isDown || this.keys.D.isDown || this.touch.right;
    const jumpHeld = this.cursors.up.isDown || this.keys.W.isDown ||
                      this.keys.SPACE.isDown || this.touch.jump;
    const jumpPressed = Phaser.Input.Keyboard.JustDown(this.cursors.up) ||
                         Phaser.Input.Keyboard.JustDown(this.keys.W) ||
                         Phaser.Input.Keyboard.JustDown(this.keys.SPACE) || jumpHeld;

    if (left) { this.player.setVelocityX(-260); this.player.setFlipX(true); }
    else if (right) { this.player.setVelocityX(260); this.player.setFlipX(false); }
    else { this.player.setVelocityX(this.player.body.velocity.x * 0.72); }

    // coyote time: still allowed to jump for a few frames after leaving a ledge
    this.coyote = onGround ? 120 : Math.max(0, this.coyote - delta);
    // jump buffer: a press just before landing still triggers the jump
    this.jumpBuffer = jumpPressed ? 140 : Math.max(0, this.jumpBuffer - delta);

    if (this.jumpBuffer > 0 && this.coyote > 0 && this.player.body.velocity.y >= -50) {
      this.player.setVelocityY(-800);
      this.coyote = 0;
      this.jumpBuffer = 0;
      this.player.setScale(0.82, 1.18);
      this.tweens.add({ targets: this.player, scaleX: 1, scaleY: 1, duration: 220, ease: 'Back.easeOut' });

      // little dust puff on jump
      for (let i = 0; i < 5; i++) {
        const p = this.add.image(this.player.x, this.player.y + 20, 'spark')
          .setDepth(5).setTint(0xffe3c2).setScale(0.8);
        this.tweens.add({
          targets: p, x: p.x + Phaser.Math.Between(-20, 20), alpha: 0,
          y: p.y + 6, duration: 300, onComplete: () => p.destroy()
        });
      }
    }

    // gentle squash while falling fast, stretch while rising
    if (!onGround) {
      const vy = this.player.body.velocity.y;
      const stretch = Phaser.Math.Clamp(vy / 900, -0.18, 0.22);
      this.player.setScale(1 - stretch * 0.5, 1 + stretch * 0.5);
    } else if (Math.abs(this.player.body.velocity.x) < 10) {
      this.player.setScale(1, 1);
    }

    if (onGround && this.player.y < GAME_H - 40) {
      this.checkpoint.x = this.player.x;
      this.checkpoint.y = this.player.y - 20;
    }

    if (this.player.y > GAME_H + 120) this.takeDamage();

    this.hazards.children.iterate((h) => {
      if (!h || h.minY === undefined) return;
      if (h.y < h.minY) h.setVelocityY(90);
      if (h.y > h.maxY) h.setVelocityY(-90);
    });

    const dist = Math.abs(this.player.x - this.templeX);
    this.gateText.setText(
      dist < 520
        ? (this.wisdom >= NEED_WISDOM
            ? 'THE GATE IS OPEN'
            : `NEED ${NEED_WISDOM - this.wisdom} MORE WISDOM`)
        : ''
    );

    const secs = Math.floor((time - this.startTime) / 1000);
    this.timeText.setText(`TIME  ${String(Math.floor(secs / 60)).padStart(2, '0')}:${String(secs % 60).padStart(2, '0')}`);
  }
}

/* ============================================================
   END SCENE  -  result + restart
   ============================================================ */
class EndScene extends Phaser.Scene {
  constructor() { super('End'); }
  init(data) { this.result = data; }

  create() {
    const { won, wisdom, lives, seconds } = this.result;
    paintFestiveSky(this, GAME_W);
    this.cameras.main.fadeIn(500, 0, 0, 0);

    if (won) {
      // ---- fireworks: several bursts of radiating sparks across the sky ----
      const fwColors = [COL_MAGENTA, COL_TEAL, COL_GOLD, COL_PURPLE, 0xff7f4d, 0xffffff];
      const launchFirework = (fx, fy) => {
        const color = fwColors[Phaser.Math.Between(0, fwColors.length - 1)];
        // flash ring
        const ring = this.add.circle(fx, fy, 4, color, 0.9).setDepth(50);
        this.tweens.add({
          targets: ring, radius: 90, alpha: 0, duration: 700, ease: 'Cubic.easeOut',
          onComplete: () => ring.destroy()
        });
        // radiating sparks
        const sparkCount = 22;
        for (let i = 0; i < sparkCount; i++) {
          const angle = (Math.PI * 2 * i) / sparkCount;
          const dist = Phaser.Math.Between(70, 130);
          const s = this.add.circle(fx, fy, Phaser.Math.Between(2, 4), color, 1).setDepth(50);
          this.tweens.add({
            targets: s,
            x: fx + Math.cos(angle) * dist,
            y: fy + Math.sin(angle) * dist + 30, // gentle gravity drift
            alpha: 0,
            duration: Phaser.Math.Between(900, 1300),
            ease: 'Cubic.easeOut',
            onComplete: () => s.destroy()
          });
        }
      };

      // schedule a handful of bursts, staggered, spread across the sky
      const burstSpots = [
        [GAME_W * 0.2, GAME_H * 0.28], [GAME_W * 0.5, GAME_H * 0.18],
        [GAME_W * 0.78, GAME_H * 0.32], [GAME_W * 0.35, GAME_H * 0.22],
        [GAME_W * 0.62, GAME_H * 0.30], [GAME_W * 0.5, GAME_H * 0.42]
      ];
      burstSpots.forEach(([fx, fy], i) => {
        this.time.delayedCall(i * 260, () => launchFirework(fx, fy));
      });
      this.time.addEvent({
        delay: 900, loop: true, repeat: 6,
        callback: () => launchFirework(
          Phaser.Math.Between(GAME_W * 0.15, GAME_W * 0.85),
          Phaser.Math.Between(GAME_H * 0.15, GAME_H * 0.45)
        )
      });

      // confetti burst
      const colors = [COL_MAGENTA, COL_TEAL, COL_GOLD, COL_PURPLE, 0xff7f4d];
      for (let i = 0; i < 60; i++) {
        const c = this.add.rectangle(
          GAME_W / 2, -20, 8, 14, colors[i % colors.length]
        ).setAngle(Phaser.Math.Between(0, 360));
        this.tweens.add({
          targets: c,
          x: GAME_W / 2 + Phaser.Math.Between(-500, 500),
          y: GAME_H + 40,
          angle: c.angle + Phaser.Math.Between(200, 600),
          duration: Phaser.Math.Between(1600, 3000),
          delay: Phaser.Math.Between(0, 500),
          ease: 'Cubic.easeIn'
        });
      }
    }

    const timeBonus = won ? Math.max(0, 600 - seconds * 5) : 0;
    const lampBonus = won ? lives * 150 : 0;
    const score = wisdom * 10 + lampBonus + timeBonus;

    this.add.text(GAME_W / 2, 120, won ? 'THE PANDAL WELCOMES YOU' : 'THE PATH CLAIMED YOUR LIGHT', {
      fontFamily: 'Georgia, serif', fontSize: won ? '54px' : '44px',
      color: won ? '#ffc94a' : '#ff8fae'
    }).setOrigin(0.5).setShadow(0, 0, won ? '#ff5e8f' : '#8b2040', 26, false, true);

    if (won) {
      this.add.text(GAME_W / 2, 184, 'गणपति बप्पा मोरया', {
        fontFamily: 'Georgia, serif', fontSize: '26px', color: '#fff0c4'
      }).setOrigin(0.5);
    }

    const rows = [
      ['Wisdom gathered', `${wisdom} × 10 = ${wisdom * 10}`],
      ['Diyas remaining', `${lives} × 150 = ${lampBonus}`],
      ['Time bonus', `${timeBonus}`],
      ['Time taken', `${Math.floor(seconds / 60)}m ${seconds % 60}s`]
    ];

    rows.forEach(([label, value], i) => {
      const y = 280 + i * 42;
      this.add.text(GAME_W / 2 - 240, y, label, {
        fontFamily: 'Georgia, serif', fontSize: '22px', color: '#ffe3c2'
      }).setOrigin(0, 0.5);
      this.add.text(GAME_W / 2 + 240, y, value, {
        fontFamily: 'Georgia, serif', fontSize: '22px', color: '#fff0c4'
      }).setOrigin(1, 0.5);
    });

    this.add.line(0, 0, GAME_W / 2 - 240, 462, GAME_W / 2 + 240, 462, COL_GOLD, 0.5)
      .setOrigin(0, 0);

    this.add.text(GAME_W / 2, 505, `FINAL SCORE   ${score}`, {
      fontFamily: 'Georgia, serif', fontSize: '40px', color: '#ffc94a'
    }).setOrigin(0.5);

    const btn = this.add.rectangle(GAME_W / 2, 600, 300, 62, COL_GOLD, 0.16)
      .setStrokeStyle(2, COL_GOLD).setInteractive({ useHandCursor: true });
    const txt = this.add.text(GAME_W / 2, 600, 'WALK AGAIN', {
      fontFamily: 'Georgia, serif', fontSize: '24px', color: '#ffc94a'
    }).setOrigin(0.5);
    this.tweens.add({ targets: [btn, txt], alpha: 0.55, duration: 900, yoyo: true, repeat: -1 });

    this.add.text(GAME_W / 2, GAME_H - 42,
      IS_TOUCH ? 'Tap the button to play again' : 'Press R or SPACE to play again', {
      fontFamily: 'Georgia, serif', fontSize: '17px', color: '#c9b3e0'
    }).setOrigin(0.5);

    const again = () => this.scene.start('Game');
    btn.on('pointerdown', again);
    this.input.keyboard.on('keydown-R', again);
    this.input.keyboard.on('keydown-SPACE', again);
  }
}

/* ============================================================
   GAME CONFIG
   ============================================================ */
new Phaser.Game({
  type: Phaser.AUTO,
  parent: 'app',
  backgroundColor: '#2d1b4e',
  scale: {
    mode: Phaser.Scale.FIT,
    autoCenter: Phaser.Scale.CENTER_BOTH,
    width: GAME_W,
    height: GAME_H
  },
  physics: {
    default: 'arcade',
    arcade: { gravity: { y: 1500 }, debug: false }
  },
  scene: [BootScene, MenuScene, GameScene, EndScene]
});